CREATE DATABASE IF NOT EXISTS flower_coin CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE flower_coin;
DROP TABLE IF EXISTS merge_history,box_history,coin_transactions,inventory,gardens,users;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,coins DECIMAL(18,4) NOT NULL DEFAULT 500,pending_coins DECIMAL(18,4) NOT NULL DEFAULT 0,mode ENUM('night','day') NOT NULL DEFAULT 'night',last_tick DATETIME NULL,day_started_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE gardens(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,slot TINYINT UNSIGNED NOT NULL,flower_tier TINYINT UNSIGNED NULL,planted_at DATETIME NULL,UNIQUE KEY uq(user_id,slot),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE inventory(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,flower_tier TINYINT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL DEFAULT 0,UNIQUE KEY uq_inv(user_id,flower_tier),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE coin_transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,amount DECIMAL(18,4) NOT NULL,type VARCHAR(40) NOT NULL,description VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE box_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,flower_tier TINYINT UNSIGNED NOT NULL,cost DECIMAL(18,4) DEFAULT 100,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE merge_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,from_tier TINYINT UNSIGNED NOT NULL,to_tier TINYINT UNSIGNED NOT NULL,success TINYINT(1) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
